// Aggregate metrics from all sources
const health = $input.item.json;
const observatory = $input.item.json;
const indicators = $input.item.json;
const leads = $input.item.json.results || [];
const newLeads = $input.item.json.results || [];
const demoBooked = $input.item.json.results || [];
const customers = $input.item.json.results || [];

// CLI Market metrics
const maa = observatory.maa || 0;
const activeAgents = observatory.active_agents || 0;
const retailers = observatory.retailers_count || 0;
const countries = observatory.countries_count || 0;

// Sales metrics
const newLeadsCount = newLeads.length;
const demoBookedCount = demoBooked.length;
const customerCount = customers.length;

// Calculate conversion rates
const demoRate = newLeadsCount > 0 ? ((demoBookedCount / newLeadsCount) * 100).toFixed(1) : 0;
const customerRate = demoBookedCount > 0 ? ((customerCount / demoBookedCount) * 100).toFixed(1) : 0;

// Revenue estimation (assuming $39 average for Pro)
const mrr = customerCount * 39;

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    cli_market: {
      maa: maa,
      active_agents: activeAgents,
      retailers: retailers,
      countries: countries
    },
    sales: {
      new_leads: newLeadsCount,
      demo_booked: demoBookedCount,
      customers: customerCount,
      demo_rate: `${demoRate}%`,
      customer_rate: `${customerRate}%`
    },
    revenue: {
      mrr: mrr,
      arr: mrr * 12
    }
  }
};

// Format daily briefing for Slack
const metrics = $input.item.json;
const date = metrics.date;

const cliMarket = metrics.cli_market;
const sales = metrics.sales;
const revenue = metrics.revenue;

const cliMarketSection = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*CLI Market Metrics:*'
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*MAA:*\n${cliMarket.maa.toLocaleString()}`
      },
      {
        type: 'mrkdwn',
        text: `*Active Agents:*\n${cliMarket.active_agents.toLocaleString()}`
      },
      {
        type: 'mrkdwn',
        text: `*Retailers:*\n${cliMarket.retailers}`
      },
      {
        type: 'mrkdwn',
        text: `*Countries:*\n${cliMarket.countries}`
      }
    ]
  }
];

const salesSection = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Sales Pipeline:*'
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*New Leads:*\n${sales.new_leads}`
      },
      {
        type: 'mrkdwn',
        text: `*Demo Booked:*\n${sales.demo_booked}`
      },
      {
        type: 'mrkdwn',
        text: `*Customers:*\n${sales.customers}`
      },
      {
        type: 'mrkdwn',
        text: `*Demo Rate:*\n${sales.demo_rate}`
      }
    ]
  }
];

const revenueSection = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Revenue:*'
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*MRR:*\n$${revenue.mrr.toLocaleString()}`
      },
      {
        type: 'mrkdwn',
        text: `*ARR:*\n$${revenue.arr.toLocaleString()}`
      },
      {
        type: 'mrkdwn',
        text: `*Customer Rate:*\n${sales.customer_rate}`
      },
      {
        type: 'mrkdwn',
        text: `*Date:*\n${date}`
      }
    ]
  }
];

return {
  json: {
    channel: '#command-control',
    text: `📊 Daily Command Control - ${date}`,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: `📊 Daily Command Control - ${date}`
        }
      },
      ...cliMarketSection,
      {
        type: 'divider'
      },
      ...salesSection,
      {
        type: 'divider'
      },
      ...revenueSection,
      {
        type: 'actions',
        elements: [
          {
            type: 'button',
            text: {
              type: 'plain_text',
              text: 'View HubSpot Pipeline'
            },
            url: 'https://app.hubspot.com/contacts/YOUR_PORTAL/pipeline'
          },
          {
            type: 'button',
            text: {
              type: 'plain_text',
              text: 'View CLI Market Stats'
            },
            url: 'https://cli-market.dev/stats'
          }
        ]
      }
    ]
  }
};
